def test_workflow_is_read_only_same_repo_hosted_and_separate_from_qualification():
    workflow = (
        Path(__file__).resolve().parents[2]
        / ".github/workflows/python-lock-bootstrap.yml"
    ).read_text()
    assert "pull_request_target" not in workflow
    assert "workflow_dispatch" not in workflow
    assert "contents: read" in workflow and "contents: write" not in workflow
    assert "head.repo.full_name == github.repository" in workflow
    assert "persist-credentials: false" in workflow
    assert "fetch-depth: 0" in workflow
    assert "retention-days: 7" in workflow
    assert "environment:" not in workflow and "secrets." not in workflow
    assert workflow.index("--validate") < workflow.index(
        "./.github/actions/setup-poetry"
    )
    assert "poetry install" not in workflow and "pytest" not in workflow


def test_generated_lock_cannot_claim_hashes_for_tool_modified_source(
    checkout, tmp_path, monkeypatch
):
    repo, _ = checkout
    proposal_path = repo / "proposal.json"
    proposal_path.write_text(json.dumps(_document()))

    def command(arguments, cwd, *, capture_stdout):
        if arguments == ("poetry", "--version"):
            return b"Poetry (version 2.4.1)"
        assert arguments == ("poetry", "lock", "--no-interaction")
        (cwd / "pyproject.toml").write_text(ROOT + "# tool mutation\n")
        return b""

    monkeypatch.setattr(producer, "_command", command)
    output = tmp_path / "artifact"
    with pytest.raises(producer.BootstrapError):
        producer.produce_lock(repo, proposal_path, output)
